18	/// Split a 32-byte secret into 3 Shamir shares using a 2-of-3 threshold.
19	///
20	/// Any 2 of the 3 returned shares can reconstruct the original secret via
21	/// [`combine_shares`]. A single share reveals nothing about the secret
22	/// (information-theoretic security).
23	///
24	/// Uses GF(2^8) arithmetic with the AES irreducible polynomial
25	/// p(x) = x^8 + x^4 + x^3 + x + 1 (0x11b).
26	pub fn split_secret(secret: &[u8; 32]) -> Result<[ShamirShare; 3], CryptoError> {
27	    let mut coeffs = Zeroizing::new([0u8; 32]);
28	    OsRng
29	        .try_fill_bytes(coeffs.as_mut())
30	        .map_err(|e| CryptoError::SecretSharing(format!("OS RNG unavailable: {e}")))?;
31	
32	    let mut s1 = Zeroizing::new([0u8; 32]);
33	    let mut s2 = Zeroizing::new([0u8; 32]);
34	    let mut s3 = Zeroizing::new([0u8; 32]);
35	
36	    // Polynomial: f(x) = secret[i] + coeffs[i]·x in GF(2^8).
37	    // f(0) = secret[i]. Shares are f(1), f(2), f(3).
38	    //
39	    // Secret-bearing coefficient bytes are in the first argument of gf_mul.
40	    // The polynomial reduction inside gf_mul is branchless (mask-based), so
41	    // bit patterns of the coefficients are not observable through branch
42	    // timing. The `if b & 1` branch in gf_mul is on the public share index.
43	    for i in 0..32 {
44	        let s = secret[i];
45	        let a = coeffs[i];
46	        s1[i] = gf_add(s, gf_mul(a, 1));
47	        s2[i] = gf_add(s, gf_mul(a, 2));
48	        s3[i] = gf_add(s, gf_mul(a, 3));
49	    }
50	
51	    Ok([
52	        ShamirShare { index: 1, data: s1 },
53	        ShamirShare { index: 2, data: s2 },
54	        ShamirShare { index: 3, data: s3 },
55	    ])
56	}
