58	/// Reconstruct the original secret from any 2 Shamir shares.
59	///
60	/// The two shares must have distinct indices in the range [1, 3].
61	/// Returns [`CryptoError::SecretReconstruction`] for invalid input.
62	///
63	/// # Algorithm
64	///
65	/// Lagrange interpolation at x=0 in GF(2^8). For two points (x_a, y_a)
66	/// and (x_b, y_b) on the degree-1 polynomial f(x) = secret + coeff·x:
67	///
68	/// ```text
69	/// Standard Lagrange:  f(0) = y_a · (0−x_b)/(x_a−x_b) + y_b · (0−x_a)/(x_b−x_a)
70	/// In GF(2^8) (−x = x):  f(0) = y_a · x_b/(x_a⊕x_b) ⊕ y_b · x_a/(x_a⊕x_b)
71	/// ```
72	pub fn combine_shares(
73	    a: &ShamirShare,
74	    b: &ShamirShare,
75	) -> Result<Zeroizing<[u8; 32]>, CryptoError> {
76	    if a.index == 0 || a.index > 3 || b.index == 0 || b.index > 3 {
77	        return Err(CryptoError::SecretReconstruction(
78	            "share index must be in [1, 3]".into(),
79	        ));
80	    }
81	    if a.index == b.index {
82	        return Err(CryptoError::SecretReconstruction(
83	            "shares must have distinct indices".into(),
84	        ));
85	    }
86	
87	    let x_a = a.index;
88	    let x_b = b.index;
89	    // x_a ⊕ x_b is guaranteed nonzero since x_a ≠ x_b; gf_div cannot fail here.
90	    let denom = gf_add(x_a, x_b);
91	    // Lagrange basis values at x=0, derived from public indices — timing is fine.
92	    let l_a = gf_div(x_b, denom)?;
93	    let l_b = gf_div(x_a, denom)?;
94	
95	    let mut secret = Zeroizing::new([0u8; 32]);
96	    for i in 0..32 {
97	        // Secret share bytes are in the first argument of gf_mul (branchless reduction).
98	        secret[i] = gf_add(gf_mul(a.data[i], l_a), gf_mul(b.data[i], l_b));
99	    }
100	    Ok(secret)
101	}
