56	/// Build the public [`P256Keypair`] representation (did:key URI, multibase public key, and
57	/// zeroized private scalar) from a P-256 `SecretKey`. Shared by [`generate_p256_keypair`] and
58	/// [`derive_recovery_keypair`] so both emit byte-identical did:key encodings.
59	fn keypair_from_secret_key(secret_key: &SecretKey) -> P256Keypair {
60	    let public_key = secret_key.public_key();
61	
62	    // Compressed point: 0x02/0x03 prefix byte + 32-byte x-coordinate = 33 bytes.
63	    let compressed = public_key.to_encoded_point(true);
64	    let compressed_bytes = compressed.as_bytes();
65	
66	    // did:key multikey: P-256 multicodec varint + compressed public key bytes.
67	    let mut multikey = Vec::with_capacity(P256_MULTICODEC_PREFIX.len() + compressed_bytes.len());
68	    multikey.extend_from_slice(P256_MULTICODEC_PREFIX);
69	    multikey.extend_from_slice(compressed_bytes);
70	
71	    // multibase::encode with Base58Btc prepends the 'z' prefix automatically.
72	    let multibase_encoded = multibase::encode(Base::Base58Btc, &multikey);
73	    let key_id = DidKeyUri(format!("did:key:{multibase_encoded}"));
74	    let public_key_str = multibase::encode(Base::Base58Btc, compressed_bytes);
75	
76	    // Copy private key bytes into a Zeroizing wrapper.
77	    let raw_bytes = Zeroizing::new(secret_key.to_bytes());
78	    let mut private_key_bytes = Zeroizing::new([0u8; 32]);
79	    private_key_bytes.copy_from_slice(raw_bytes.as_slice());
80	
81	    P256Keypair {
82	        key_id,
83	        public_key: public_key_str,
84	        private_key_bytes,
85	    }
86	}
