637	function removeIdentity(state: WalletState, did: string): RemovalOutcome {
638	  const before = state.identities.length;
639	  state.identities = state.identities.filter((i) => i.did !== did);
640	  return {
641	    tombstoneCid: `bafyharnesstombstone${did.slice(-6)}`,
642	    wasLastIdentity: before > 0 && state.identities.length === 0,
643	  };
644	}
