651	function isoInHours(hours: number): string {
652	  const base = Date.parse('2026-07-15T12:00:00.000Z');
653	  return new Date(base + hours * 3600_000).toISOString();
654	}

1	/**
2	 * Stateful in-memory fake for the identity-wallet harness (browser test mode).
3	 *
4	 * Pure TypeScript: no Tauri, no DOM, no network — so it is unit-testable in the
5	 * Node vitest environment (see `state.test.ts`). The registry (`registry.ts`) owns
6	 * the command→handler mapping and mutates a {@link WalletState} instance through the
7	 * helpers here; scenarios (`scenarios.ts`) seed fresh states from presets.
8	 *
9	 * The domain modeled mirrors what the wallet's screens actually read: managed
10	 * identities (each with a PLC-format DID document, a device key, PLC-monitor alerts,
11	 * and bound agents), plus the transient state the multi-step create / claim /
12	 * migration flows thread across commands.
13	 */
14	import type { UnauthorizedChange } from '$lib/ipc';
15	import type {
16	  AgentSummary,
17	  AgentAuditEvent,
18	  AppPasswordEntry,
19	} from '$lib/ipc';
20	
21	/** A `did:key` multibase string that is stable for a given seed (not a real key). */
22	export function fakeDeviceKeyId(seed: string): string {
23	  return `did:key:zHarnessDev${hashToken(seed)}`;
24	}
25	
26	/** A plausible-looking `did:plc` for a given seed. */
27	export function fakePlcDid(seed: string): string {
28	  return `did:plc:harness${hashToken(seed)}`;
29	}
30	
31	/** Deterministic base36-ish token from a string — keeps fakes readable and stable. */
32	function hashToken(seed: string): string {
33	  let h = 2166136261;
34	  for (let i = 0; i < seed.length; i++) {
35	    h = (h ^ seed.charCodeAt(i)) >>> 0;
36	    h = (h * 16777619) >>> 0;
37	  }
38	  return h.toString(36).padStart(7, '0').slice(0, 12);
39	}
