143	/**
144	 * Seed a fresh identity. `deviceKeyIsRoot` controls whether the device key sits at
145	 * `rotationKeys[0]` — the "Root key" badge on the home card depends on this.
146	 */
147	export function seedIdentity(
148	  opts: {
149	    handle: string;
150	    pdsUrl?: string;
151	    did?: string;
152	    deviceKeyIsRoot?: boolean;
153	  }
154	): FakeIdentity {
155	  const pdsUrl = opts.pdsUrl ?? DEFAULT_PDS_URL;
156	  const did = opts.did ?? fakePlcDid(opts.handle);
157	  const deviceKeyId = fakeDeviceKeyId(did);
158	  const deviceKeyIsRoot = opts.deviceKeyIsRoot ?? true;
159	  const pdsKey = fakeDeviceKeyId(`${did}:pds`);
160	  const rotationKeys = deviceKeyIsRoot ? [deviceKeyId, pdsKey] : [pdsKey, deviceKeyId];
161	  return {
162	    did,
163	    handle: opts.handle,
164	    pdsUrl,
165	    deviceKeyId,
166	    rotationKeys,
167	    alerts: [],
168	    agents: [],
169	    appPasswords: [],
170	  };
171	}
