183	/** Build a fake claimed agent with a minimal audit trail. */
184	export function seedAgent(seed: string, did: string): FakeAgent {
185	  const registrationId = `reg-${hashToken(seed)}`;
186	  const now = '2026-07-15T12:00:00.000Z';
187	  return {
188	    summary: {
189	      registrationId,
190	      registrationType: 'service_auth',
191	      issuer: `did:web:agent-${hashToken(seed)}.example`,
192	      subject: did,
193	      scopes: ['repo:write', 'blob:upload'],
194	      status: 'claimed',
195	      createdAt: now,
196	      updatedAt: now,
197	      lastUsedAt: now,
198	    },
199	    audit: [
200	      { id: `ev-${hashToken(seed)}-1`, eventType: 'registered', createdAt: now },
201	      { id: `ev-${hashToken(seed)}-2`, eventType: 'claim_confirmed', did, createdAt: now },
202	      { id: `ev-${hashToken(seed)}-3`, eventType: 'token_exchanged', createdAt: now },
203	    ],
