207	/** Build a fake app-password entry (metadata only, mirroring the real list route). */
208	export function seedAppPassword(name: string, privileged = false): AppPasswordEntry {
209	  return {
210	    name,
211	    createdAt: '2026-07-15T12:00:00.000Z',
212	    privileged,
213	  };
214	}
215	
216	/** The deterministic one-time secret the fake `create_app_password` returns for a name. */
217	export function fakeAppPasswordSecret(name: string): string {
218	  // hashToken yields 7 chars, so three rounds guarantee the full 16-char secret shape.
219	  const token = `${hashToken(name)}${hashToken(`${name}:pad`)}${hashToken(`${name}:pad2`)}`.slice(
220	    0,
221	    16
222	  );
223	  return `${token.slice(0, 4)}-${token.slice(4, 8)}-${token.slice(8, 12)}-${token.slice(12, 16)}`;
224	}
