226	/** Find a managed identity by DID, or undefined. */
227	export function findIdentity(state: WalletState, did: string): FakeIdentity | undefined {
228	  return state.identities.find((i) => i.did === did);
229	}
230	
231	/** Register (or replace) an identity in the store. Idempotent by DID. */
232	export function upsertIdentity(state: WalletState, identity: FakeIdentity): void {
233	  const idx = state.identities.findIndex((i) => i.did === identity.did);
234	  if (idx === -1) state.identities.push(identity);
235	  else state.identities[idx] = identity;
236	}
