3	//! Queries over `recovery_escrow` (V050): the PDS-held Shamir Share 2 for
4	//! accounts on the client-generated share model, one row per DID.
5	//!
6	//! Rows store only the KEK-wrapped share envelope ciphertext (wrapping and
7	//! unwrapping live in the caller — this module moves opaque ciphertext, like
8	//! `db/kek.rs`). The deposit/replace/delete steps are generic over the
9	//! executor so the owner endpoints can compose them with their audit-event
10	//! insert in one transaction.
11	
12	use sqlx::Sqlite;
13	
14	/// Whether an account currently holds an escrow row. The deposit endpoint
15	/// uses this (inside its transaction) to pick insert-vs-replace and the
16	/// matching audit event; readers of the ciphertext itself arrive with the
17	/// escrow release flow.
18	pub(crate) async fn escrow_share_exists<'e, E>(executor: E, did: &str) -> Result<bool, sqlx::Error>
19	where
20	    E: sqlx::Executor<'e, Database = Sqlite>,
21	{
22	    sqlx::query_scalar("SELECT EXISTS(SELECT 1 FROM recovery_escrow WHERE did = ?)")
23	        .bind(did)
24	        .fetch_one(executor)
25	        .await
26	}
27	
28	/// Insert the account's first escrow row (the initial deposit).
29	pub(crate) async fn insert_escrow_share<'e, E>(
30	    executor: E,
31	    did: &str,
32	    share_encrypted: &str,
33	) -> Result<(), sqlx::Error>
34	where
35	    E: sqlx::Executor<'e, Database = Sqlite>,
36	{
37	    sqlx::query(
38	        "INSERT INTO recovery_escrow (did, share_encrypted, created_at) \
39	         VALUES (?, ?, datetime('now'))",
40	    )
41	    .bind(did)
42	    .bind(share_encrypted)
43	    .execute(executor)
44	    .await?;
45	    Ok(())
46	}
47	
48	/// Replace an existing escrow row's ciphertext, stamping `rotated_at` and
49	/// clearing any in-flight release state — a replacement share voids a pending
50	/// release of the old one. Returns whether a row was actually replaced, so the
51	/// caller can pick insert-vs-replace without a race window (single-connection
52	/// pool, and the caller runs both inside one transaction anyway).
53	pub(crate) async fn replace_escrow_share<'e, E>(
54	    executor: E,
55	    did: &str,
56	    share_encrypted: &str,
57	) -> Result<bool, sqlx::Error>
58	where
59	    E: sqlx::Executor<'e, Database = Sqlite>,
60	{
61	    let result = sqlx::query(
62	        "UPDATE recovery_escrow SET \
63	             share_encrypted = ?, \
64	             rotated_at = datetime('now'), \
65	             release_requested_at = NULL, \
66	             release_pending_until = NULL \
67	         WHERE did = ?",
68	    )
69	    .bind(share_encrypted)
70	    .bind(did)
71	    .execute(executor)
72	    .await?;
73	    Ok(result.rows_affected() == 1)
74	}
75	
76	/// Delete an account's escrow row (owner opt-out). Returns whether a row
77	/// existed — the caller audits only a real deletion, keeping the repeat call
78	/// an idempotent no-op with no duplicate event.
79	pub(crate) async fn delete_escrow_share<'e, E>(executor: E, did: &str) -> Result<bool, sqlx::Error>
80	where
81	    E: sqlx::Executor<'e, Database = Sqlite>,
82	{
83	    let result = sqlx::query("DELETE FROM recovery_escrow WHERE did = ?")
84	        .bind(did)
85	        .execute(executor)
86	        .await?;
87	    Ok(result.rows_affected() == 1)
88	}
