1	// pattern: Imperative Shell
2	//
3	// Owner endpoints for the PDS-held Shamir Share 2 (the escrow half of share-based recovery):
4	//
5	//   PUT    /v1/recovery/escrow-share — deposit or replace the account's Share 2 envelope
6	//   DELETE /v1/recovery/escrow-share — opt out of escrow entirely (idempotent)
7	//
8	// The share arrives as the v2 base32 share envelope the wallet produced client-side; the server
9	// validates it structurally (well-formed envelope, index 2 — Custos never holds any other share)
10	// and stores only the AES-256-GCM master-KEK wrapping of its 42 envelope bytes
11	// (`crypto::encrypt_secret_bytes`, the shared `SecretFamily` ciphertext format — the base
12	// envelope deliberately, with no per-row AAD divergence from the other wrapped columns). One
13	// share is information-theoretically worthless alone, so the wrapping is defense-in-depth: a raw
14	// DB dump or backup never exposes even that.
15	//
16	// Each state change appends its `recovery_audit_events` row in the same transaction
17	// (`deposited` / `rotated` / `deleted` — mechanical facts only, never share material). The
18	// repeat DELETE is a 200 no-op with no duplicate event.
19	//
20	// Auth is `auth::guards::authenticate_account_owner` (wallet session token or full-access
21	// OAuth/XRPC token; agent-derived and app-password credentials refused) — the ceremony deposit,
22	// the rotation epilogue, and the old-account re-key all act as the owner. These live on the
23	// same-origin `/v1/*` surface (no permissive CORS).
24	
25	use axum::{
26	    extract::State,
27	    http::{HeaderMap, Method, Uri},
28	    Json,
29	};
30	use serde::{Deserialize, Serialize};
31	use uuid::Uuid;
32	
33	use crate::app::AppState;
34	use crate::auth::guards::{authenticate_account_owner, OwnerAuthError};
35	use crate::db::recovery_audit::{insert_recovery_audit_event, RecoveryAuditEventType};
36	use crate::db::recovery_escrow::{
37	    delete_escrow_share, escrow_share_exists, insert_escrow_share, replace_escrow_share,
38	};
39	use common::{ApiError, ErrorCode};
40	
41	/// Authenticate the account owner and map the neutral rejection into this surface's vocabulary.
42	/// Mirrors `agents.rs`'s wrapper (routes may not import one another).
43	async fn authenticate_owner(
44	    headers: &HeaderMap,
45	    method: &Method,
46	    uri: &Uri,
47	    state: &AppState,
48	) -> Result<String, ApiError> {
49	    authenticate_account_owner(headers, method, uri, state)
50	        .await
51	        .map_err(|err| match err {
52	            OwnerAuthError::Unauthenticated(e) => e,
53	            OwnerAuthError::AgentDerived => ApiError::new(
54	                ErrorCode::InsufficientScope,
55	                "this operation is not available to agent-derived credentials",
56	            ),
57	            OwnerAuthError::NotFullAccess => ApiError::new(
58	                ErrorCode::InvalidToken,
59	                "a session or full-access token is required",
60	            ),
61	        })
62	}
63	
64	/// The escrow slot always holds Share 2 — the index reserved for Custos in the 2-of-3 split.
65	const ESCROW_SHARE_INDEX: u8 = 2;
66	
67	// ── PUT /v1/recovery/escrow-share ─────────────────────────────────────────────
68	
69	#[derive(Deserialize)]
70	pub struct PutEscrowShareRequest {
71	    /// The base32-encoded v2 share envelope (as produced by the wallet's client-side split).
72	    pub share: String,
73	}
74	
75	#[derive(Serialize)]
76	pub struct PutEscrowShareResponse {
77	    /// `"deposited"` for an account's first escrow, `"rotated"` for a replacement.
78	    pub status: &'static str,
79	}
80	
81	pub async fn put_escrow_share(
82	    State(state): State<AppState>,
83	    method: Method,
84	    uri: Uri,
85	    headers: HeaderMap,
86	    Json(payload): Json<PutEscrowShareRequest>,
87	) -> Result<Json<PutEscrowShareResponse>, ApiError> {
88	    let did = authenticate_owner(&headers, &method, &uri, &state).await?;
89	
90	    // Structural validation before anything is stored: a malformed or corrupted share fails
91	    // loudly now, not at recovery time. Decode errors are reported by kind (version / checksum /
92	    // format — `decode_share` distinguishes them) but never echo the submitted material.
93	    let envelope = crypto::ShareEnvelope::decode_share(&payload.share)
94	        .map_err(|e| ApiError::new(ErrorCode::InvalidRequest, format!("invalid share: {e}")))?;
95	    if envelope.index() != ESCROW_SHARE_INDEX {
96	        return Err(ApiError::new(
97	            ErrorCode::InvalidRequest,
98	            "escrow holds Share 2 only; refusing a share with a different index",
99	        ));
100	    }
101	
102	    let master_key: &[u8; 32] = state
103	        .config
104	        .signing_key_master_key
105	        .as_ref()
106	        .map(|s| &*s.0)
107	        .ok_or_else(|| {
108	            ApiError::new(
109	                ErrorCode::ServiceUnavailable,
110	                "signing key master key not configured",
111	            )
112	        })?;
113	    let wrapped = crypto::encrypt_secret_bytes(envelope.to_bytes().as_slice(), master_key)
114	        .map_err(|e| {
115	            tracing::error!(error = %e, "failed to wrap escrow share");
116	            ApiError::new(ErrorCode::InternalError, "failed to store escrow share")
117	        })?;
118	
119	    let map_err = |e: sqlx::Error| {
120	        tracing::error!(did = %did, error = %e, "DB error storing escrow share");
121	        ApiError::new(ErrorCode::InternalError, "failed to store escrow share")
122	    };
123	
124	    // Replace-or-insert plus its audit event, atomically. `detail` records the envelope's
125	    // non-secret metadata so a rotation is auditable against the share generation it installed.
126	    let mut tx = state.db.begin().await.map_err(map_err)?;
127	    let event = if escrow_share_exists(&mut *tx, &did).await.map_err(map_err)? {
128	        replace_escrow_share(&mut *tx, &did, &wrapped)
129	            .await
130	            .map_err(map_err)?;
131	        RecoveryAuditEventType::Rotated
132	    } else {
133	        insert_escrow_share(&mut *tx, &did, &wrapped)
134	            .await
135	            .map_err(map_err)?;
136	        RecoveryAuditEventType::Deposited
137	    };
138	    let detail = serde_json::json!({
139	        "set_id": envelope.set_id(),
140	        "version": envelope.version(),
141	    });
142	    insert_recovery_audit_event(
143	        &mut *tx,
144	        &Uuid::new_v4().to_string(),
145	        &did,
146	        event,
147	        Some(&detail.to_string()),
148	    )
149	    .await?;
150	    tx.commit().await.map_err(map_err)?;
151	
152	    Ok(Json(PutEscrowShareResponse {
153	        status: event.as_str(),
154	    }))
155	}
156	
157	// ── DELETE /v1/recovery/escrow-share ──────────────────────────────────────────
158	
159	#[derive(Serialize)]
160	pub struct DeleteEscrowShareResponse {
161	    /// Always `"deleted"` — the terminal state holds whether or not a share existed.
162	    pub status: &'static str,
163	}
164	
165	pub async fn delete_escrow_share_handler(
166	    State(state): State<AppState>,
167	    method: Method,
168	    uri: Uri,
169	    headers: HeaderMap,
170	) -> Result<Json<DeleteEscrowShareResponse>, ApiError> {
171	    let did = authenticate_owner(&headers, &method, &uri, &state).await?;
172	
173	    let map_err = |e: sqlx::Error| {
174	        tracing::error!(did = %did, error = %e, "DB error deleting escrow share");
175	        ApiError::new(ErrorCode::InternalError, "failed to delete escrow share")
176	    };
177	
178	    // Delete plus its audit event, atomically — but only a real deletion is audited, so the
179	    // idempotent repeat call leaves no duplicate event.
180	    let mut tx = state.db.begin().await.map_err(map_err)?;
181	    let deleted = delete_escrow_share(&mut *tx, &did).await.map_err(map_err)?;
182	    if deleted {
183	        insert_recovery_audit_event(
184	            &mut *tx,
185	            &Uuid::new_v4().to_string(),
186	            &did,
187	            RecoveryAuditEventType::Deleted,
188	            None,
189	        )
190	        .await?;
191	    }
192	    tx.commit().await.map_err(map_err)?;
193	
194	    Ok(Json(DeleteEscrowShareResponse { status: "deleted" }))
195	}
