35	/// material — deleted by [`clear_staging`] once the ceremony is confirmed.
36	pub const STAGING_ACCOUNT: &str = "ceremony-staging";
37	
38	/// Bumped only on a breaking staging-record format change; a mismatched version
39	/// reads as corrupt and fails closed (`StagingCorrupt`).
40	const STAGING_VERSION: u32 = 1;
41	
42	#[derive(Debug, thiserror::Error)]
43	pub enum ShareCeremonyError {
44	    #[error("crypto failure: {0}")]
45	    Crypto(#[from] crypto::CryptoError),
46	    #[error("OS RNG unavailable: {0}")]
47	    Rng(String),
