58	/// The wallet-generated share set for one DID ceremony attempt (or a staged retry).
59	///
60	/// Encoded share strings are share material and ride in [`Zeroizing`] buffers, matching
61	/// the crypto crate's rule that share material never lands in non-zeroizing storage.
62	pub struct CeremonyShareSet {
63	    /// did:key URI of the recovery rotation key derived from the seed — goes into the
64	    /// genesis op's `rotationKeys` (slot \[1\]) and the ceremony request's `recoveryKey`.
65	    pub recovery_key_id: String,
66	    /// Base32 v2 envelope of Share 1 — written to the durable `recovery-share-1` slot
