68	    pub share1: Zeroizing<String>,
69	    /// Base32 v2 envelope of Share 2 — the escrow deposit sent to Custos.
70	    pub share2: Zeroizing<String>,
71	    /// Base32 v2 envelope of Share 3 — the user's manual-backup copy (QR form).
72	    pub share3: Zeroizing<String>,
73	    /// Share 3 rendered as the BIP-39-style word phrase (identical 42 bytes).
74	    pub share3_words: Zeroizing<String>,
