81	/// The share fields are share material held in plain `String`s while the record is
82	/// (de)serialized, so the record wipes them on drop (`Drop` below) — the same rule as
83	/// every other in-memory home of share material.
84	#[derive(Serialize, Deserialize)]
85	struct StagingRecord {
