105	/// Load the staged share set for `(handle, pds_url)` if a valid one exists, else
106	/// generate a fresh set and stage it — always BEFORE the caller makes any network call,
107	/// so a mid-ceremony failure retries with the identical set (same `set_id`).
108	pub fn load_or_create(handle: &str, pds_url: &str) -> Result<CeremonyShareSet, ShareCeremonyError> {
109	    if let Some(staged) = load_staged(handle, pds_url)? {
110	        return Ok(staged);
111	    }
112	
113	    let mut seed = Zeroizing::new([0u8; 32]);
114	    OsRng
115	        .try_fill_bytes(seed.as_mut())
116	        .map_err(|e| ShareCeremonyError::Rng(e.to_string()))?;
117	    let mut set_id_bytes = [0u8; 4];
118	    OsRng
119	        .try_fill_bytes(&mut set_id_bytes)
120	        .map_err(|e| ShareCeremonyError::Rng(e.to_string()))?;
