122	
123	    let envelopes = crypto::split_secret_into_envelopes(&seed, set_id)?;
124	    let recovery = crypto::derive_recovery_keypair(&seed)?;
125	
126	    let share1 = envelopes[0].encode_share();
127	    let share2 = envelopes[1].encode_share();
128	    let share3 = envelopes[2].encode_share();
129	    let share3_words = envelopes[2].encode_share_words();
130	
131	    // Stage before returning: from here on, a retry of the same ceremony must reuse
132	    // this exact set. The serialized record is share material — zeroized after the
133	    // Keychain write.
134	    let record = Zeroizing::new(
135	        serde_json::to_string(&StagingRecord {
136	            version: STAGING_VERSION,
137	            handle: handle.to_string(),
138	            pds_url: pds_url.to_string(),
139	            share1: share1.to_string(),
140	            share2: share2.to_string(),
141	            share3: share3.to_string(),
142	        })
143	        .expect("staging record serialization cannot fail"),
144	    );
145	    keychain::store_item(STAGING_ACCOUNT, record.as_bytes())?;
146	
147	    Ok(CeremonyShareSet {
148	        recovery_key_id: recovery.key_id.0,
