156	/// Read and validate the staging slot.
157	///
158	/// Fail-closed contract: only two outcomes permit generating fresh material —
159	/// `Ok(None)` for a genuinely absent slot, or for a slot staged under *different
160	/// ceremony inputs* (a new handle/PDS is a new ceremony; starting one is the user's
161	/// explicit abandonment of the old attempt, whose set can never bind to this
162	/// ceremony's genesis op). Every other defect — a transient read error, unparseable
163	/// JSON, an unsupported version, a corrupt envelope, cross-set envelopes, a failed
164	/// combine/derivation — is `Err(StagingCorrupt)`: the record may be the exact set a
165	/// prior attempt already bound to a genesis op and escrowed, so overwriting it with
166	/// unrelated shares would permanently destroy the recovery seed. The slot is
167	/// preserved for a later retry or manual inspection.
168	fn load_staged(
169	    handle: &str,
170	    pds_url: &str,
171	) -> Result<Option<CeremonyShareSet>, ShareCeremonyError> {
172	    let bytes = match keychain::get_item(STAGING_ACCOUNT) {
173	        Ok(bytes) => Zeroizing::new(bytes),
174	        Err(e) if keychain::is_not_found(&e) => return Ok(None),
175	        Err(e) => {
176	            tracing::error!(error = %e, "ceremony staging slot unreadable; failing closed");
177	            return Err(ShareCeremonyError::StagingCorrupt(format!(
178	                "keychain read failed: {e}"
179	            )));
180	        }
181	    };
182	    let record: StagingRecord = serde_json::from_slice(&bytes).map_err(|e| {
183	        tracing::error!(error = %e, "ceremony staging record unparseable; failing closed");
184	        ShareCeremonyError::StagingCorrupt(format!("unparseable staging record: {e}"))
185	    })?;
186	    if record.version != STAGING_VERSION {
187	        tracing::error!(
188	            version = record.version,
189	            "ceremony staging record has unsupported version; failing closed"
190	        );
191	        return Err(ShareCeremonyError::StagingCorrupt(format!(
192	            "unsupported staging record version {}",
193	            record.version
194	        )));
195	    }
196	    if record.handle != handle || record.pds_url != pds_url {
197	        tracing::warn!(
198	            "ceremony inputs changed since staging; abandoning the staged set and regenerating"
199	        );
200	        return Ok(None);
201	    }
202	
203	    let decode = |encoded: &str, index: u8| -> Result<crypto::ShareEnvelope, ShareCeremonyError> {
204	        match crypto::ShareEnvelope::decode_share(encoded) {
205	            Ok(env) if env.index() == index => Ok(env),
206	            Ok(env) => {
207	                tracing::error!(
208	                    expected = index,
209	                    got = env.index(),
210	                    "staged share has wrong index; failing closed"
211	                );
212	                Err(ShareCeremonyError::StagingCorrupt(format!(
213	                    "staged share has index {} where {index} was expected",
214	                    env.index()
215	                )))
216	            }
217	            Err(e) => {
218	                tracing::error!(error = %e, "staged share failed validation; failing closed");
219	                Err(ShareCeremonyError::StagingCorrupt(format!(
220	                    "staged share failed validation: {e}"
221	                )))
222	            }
223	        }
224	    };
225	    let env1 = decode(&record.share1, 1)?;
226	    let env2 = decode(&record.share2, 2)?;
227	    let env3 = decode(&record.share3, 3)?;
228	    if env1.set_id() != env2.set_id() || env2.set_id() != env3.set_id() {
229	        tracing::error!("staged shares span set_ids; failing closed");
230	        return Err(ShareCeremonyError::StagingCorrupt(
231	            "staged shares span set_ids".to_string(),
232	        ));
233	    }
234	
235	    // The seed is not stored — recompute it to re-derive the recovery key.
236	    let seed = crypto::combine_envelopes(&env1, &env2).map_err(|e| {
237	        tracing::error!(error = %e, "staged shares failed to combine; failing closed");
238	        ShareCeremonyError::StagingCorrupt(format!("staged shares failed to combine: {e}"))
239	    })?;
240	    let recovery = crypto::derive_recovery_keypair(&seed).map_err(|e| {
241	        tracing::error!(error = %e, "recovery key derivation failed on staged seed; failing closed");
242	        ShareCeremonyError::StagingCorrupt(format!("recovery key derivation failed: {e}"))
243	    })?;
244	
245	    tracing::info!(set_id = env1.set_id(), "reusing staged ceremony share set");
246	    Ok(Some(CeremonyShareSet {
247	        recovery_key_id: recovery.key_id.0,
248	        share1: env1.encode_share(),
249	        share2: env2.encode_share(),
250	        share3: env3.encode_share(),
251	        share3_words: env3.encode_share_words(),
252	    }))
253	}
