255	/// Tear down the staging slot — the seed material's last transient home. Idempotent:
256	/// an absent slot is success (the teardown already happened).
257	pub fn clear_staging() -> Result<(), keychain::KeychainError> {
258	    match keychain::delete_item(STAGING_ACCOUNT) {
259	        Ok(()) => Ok(()),
260	        Err(e) if keychain::is_not_found(&e) => Ok(()),
261	        Err(e) => Err(e),
262	    }
263	}
